<?php
/**
 * Template Name: پیشخوان کاربری
 * Template Post Type: page
 */
if ( ! defined( 'ABSPATH' ) ) { exit; }
if ( ! is_user_logged_in() ) { wp_safe_redirect( add_query_arg( 'redirect_to', rawurlencode( get_permalink() ), home_url( '/auth/' ) ) ); exit; }
get_header();
$user = wp_get_current_user();
$notice = isset( $_GET['notice'] ) ? sanitize_key( wp_unslash( $_GET['notice'] ) ) : '';
$is_analyst = current_user_can( 'revayat_submit_analyst_post' );
$special_access_status = class_exists( 'Revayat_Companion_User_Portal' ) ? Revayat_Companion_User_Portal::get_special_access_status( $user->ID ) : 'none';
$profile = $is_analyst && class_exists( 'Revayat_Companion_User_Portal' ) ? Revayat_Companion_User_Portal::get_user_profile( $user->ID ) : array();
$profile_fields = $is_analyst && class_exists( 'Revayat_Companion_User_Portal' ) ? Revayat_Companion_User_Portal::get_profile_field_options() : array();
$posts = class_exists( 'Revayat_Companion_User_Portal' ) ? Revayat_Companion_User_Portal::get_user_submissions( $user->ID, 10 ) : array();
$notifications = class_exists( 'Revayat_Companion_User_Portal' ) ? Revayat_Companion_User_Portal::get_user_notifications( $user->ID, 10 ) : array();
$unread_notifications = array_filter( $notifications, static function ( $item ) { return empty( $item['read'] ); } );
$edit_id = isset( $_GET['edit_submission'] ) ? absint( $_GET['edit_submission'] ) : 0;
$editing_submission = $edit_id && class_exists( 'Revayat_Companion_User_Portal' ) ? Revayat_Companion_User_Portal::get_editable_submission( $edit_id, $user->ID ) : null;
?>
<div class="rv-portal"><div class="container rv-dashboard">
 <header class="rv-dashboard__header"><div><span class="rv-eyebrow"><?php esc_html_e( 'پیشخوان کاربری', 'revayatiran' ); ?></span><h1><?php printf( esc_html__( 'سلام، %s', 'revayatiran' ), esc_html( $user->display_name ) ); ?></h1><p><?php echo $is_analyst ? esc_html__( 'از اینجا می‌توانید یادداشت تازه بفرستید و وضعیت بررسی مطالب را ببینید.', 'revayatiran' ) : esc_html__( 'درخواست تحلیلگری شما پس از بررسی مدیر فعال خواهد شد.', 'revayatiran' ); ?></p></div><a class="rv-logout" href="<?php echo esc_url( wp_logout_url( home_url( '/' ) ) ); ?>"><i class="ph ph-sign-out"></i><?php esc_html_e( 'خروج', 'revayatiran' ); ?></a></header>
 <?php if ( 'submitted' === $notice ) : ?><div class="rv-notice rv-notice--success"><?php esc_html_e( 'یادداشت شما در صف بررسی تحریریه قرار گرفت.', 'revayatiran' ); ?></div><?php elseif ( 'saved' === $notice ) : ?><div class="rv-notice rv-notice--success"><?php esc_html_e( 'پیش‌نویس یادداشت ذخیره شد.', 'revayatiran' ); ?></div><?php elseif ( 'profile_updated' === $notice ) : ?><div class="rv-notice rv-notice--success"><?php esc_html_e( 'پروفایل حرفه‌ای شما بروزرسانی شد.', 'revayatiran' ); ?></div><?php elseif ( 'notifications_read' === $notice ) : ?><div class="rv-notice rv-notice--success"><?php esc_html_e( 'همه اعلان‌ها خوانده شدند.', 'revayatiran' ); ?></div><?php elseif ( 'special_access_requested' === $notice ) : ?><div class="rv-notice rv-notice--success"><?php esc_html_e( 'درخواست دسترسی ویژه ثبت شد و در انتظار بررسی مدیر است.', 'revayatiran' ); ?></div><?php elseif ( 'special_access_already_active' === $notice ) : ?><div class="rv-notice rv-notice--success"><?php esc_html_e( 'دسترسی ویژه حساب شما فعال است.', 'revayatiran' ); ?></div><?php elseif ( $notice ) : ?><div class="rv-notice rv-notice--error"><?php esc_html_e( 'عملیات انجام نشد؛ اطلاعات واردشده را بررسی کنید.', 'revayatiran' ); ?></div><?php endif; ?>
 <div class="rv-dashboard__grid">
  <?php if ( $notifications ) : ?><section class="rv-dashboard-card rv-dashboard-card--wide rv-notifications"><div class="rv-dashboard-card__heading"><h2><i class="ph ph-bell"></i><?php esc_html_e( 'اعلان‌های تحریریه', 'revayatiran' ); ?><?php if ( $unread_notifications ) : ?><span class="rv-notification-count"><?php echo esc_html( revayat_en2fa( count( $unread_notifications ) ) ); ?></span><?php endif; ?></h2><?php if ( $unread_notifications ) : ?><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="revayat_mark_notifications_read"><?php wp_nonce_field( 'revayat_mark_notifications_read', 'revayat_notifications_nonce' ); ?><button type="submit" class="rv-notifications__read-all"><?php esc_html_e( 'خواندن همه', 'revayatiran' ); ?></button></form><?php endif; ?></div><div class="rv-notification-list"><?php foreach ( $notifications as $notification ) : ?><article class="rv-notification <?php echo empty( $notification['read'] ) ? 'is-unread' : ''; ?>"><i class="ph ph-<?php echo esc_attr( 'approved' === $notification['status'] ? 'check-circle' : ( 'rejected' === $notification['status'] ? 'x-circle' : 'bell-ringing' ) ); ?>"></i><div><p><?php echo esc_html( $notification['message'] ); ?></p><?php if ( $notification['created_at'] ) : ?><time datetime="<?php echo esc_attr( mysql2date( DATE_W3C, $notification['created_at'] . ' +0000', false ) ); ?>"><?php echo esc_html( revayat_en2fa( get_date_from_gmt( $notification['created_at'], 'Y/m/d H:i' ) ) ); ?></time><?php endif; ?></div></article><?php endforeach; ?></div></section><?php endif; ?>
  <section class="rv-dashboard-card"><h2><i class="ph ph-identification-card"></i><?php esc_html_e( 'وضعیت حساب', 'revayatiran' ); ?></h2><dl><div><dt><?php esc_html_e( 'ایمیل', 'revayatiran' ); ?></dt><dd><?php echo esc_html( $user->user_email ); ?></dd></div><div><dt><?php esc_html_e( 'نقش', 'revayatiran' ); ?></dt><dd><?php echo esc_html( $is_analyst ? __( 'تحلیلگر تأییدشده', 'revayatiran' ) : __( 'در انتظار تأیید', 'revayatiran' ) ); ?></dd></div></dl></section>
  <section class="rv-dashboard-card rv-special-access"><h2><i class="ph ph-shield-check"></i><?php esc_html_e( 'دسترسی اتاق وضعیت', 'revayatiran' ); ?></h2><?php if ( 'approved' === $special_access_status ) : ?><p><?php esc_html_e( 'دسترسی ویژه شما فعال است.', 'revayatiran' ); ?></p><a class="rv-special-access__link" href="<?php echo esc_url( get_post_type_archive_link( 'situation_room' ) ); ?>"><?php esc_html_e( 'ورود به اتاق وضعیت', 'revayatiran' ); ?></a><?php elseif ( 'pending' === $special_access_status ) : ?><p><?php esc_html_e( 'درخواست شما ثبت شده و در انتظار بررسی مدیر است.', 'revayatiran' ); ?></p><span class="rv-status rv-status--pending"><?php esc_html_e( 'در انتظار تأیید', 'revayatiran' ); ?></span><?php else : ?><p><?php echo 'rejected' === $special_access_status ? esc_html__( 'درخواست قبلی تأیید نشد؛ در صورت تغییر شرایط می‌توانید دوباره درخواست بدهید.', 'revayatiran' ) : esc_html__( 'محتوای اتاق وضعیت فقط پس از تأیید دسترسی ویژه نمایش داده می‌شود.', 'revayatiran' ); ?></p><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="revayat_request_special_access"><?php wp_nonce_field( 'revayat_request_special_access', 'revayat_special_access_nonce' ); ?><button type="submit"><?php esc_html_e( 'درخواست دسترسی ویژه', 'revayatiran' ); ?></button></form><?php endif; ?></section>
  <?php if ( $is_analyst && $profile ) : ?><section class="rv-dashboard-card rv-dashboard-card--wide"><div class="rv-dashboard-card__heading"><h2><i class="ph ph-user-circle"></i><?php esc_html_e( 'پروفایل حرفه‌ای', 'revayatiran' ); ?></h2><?php if ( ! empty( $profile['permalink'] ) ) : ?><a href="<?php echo esc_url( $profile['permalink'] ); ?>" target="_blank" rel="noopener"><?php esc_html_e( 'مشاهده صفحه عمومی', 'revayatiran' ); ?></a><?php endif; ?></div><form class="rv-portal-form rv-profile-form" method="post" enctype="multipart/form-data" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="revayat_update_profile"><?php wp_nonce_field( 'revayat_update_profile', 'revayat_profile_nonce' ); ?><div class="rv-profile-avatar"><?php if ( ! empty( $profile['avatar_url'] ) ) : ?><img src="<?php echo esc_url( $profile['avatar_url'] ); ?>" alt="<?php echo esc_attr( $user->display_name ); ?>"><?php else : ?><i class="ph ph-user"></i><?php endif; ?><label><?php esc_html_e( 'تصویر پروفایل', 'revayatiran' ); ?><input type="file" name="profile_avatar" accept="image/jpeg,image/png,image/webp"><small><?php esc_html_e( 'JPG، PNG یا WebP؛ حداکثر ۲ مگابایت', 'revayatiran' ); ?></small></label></div><div class="rv-profile-fields"><label><?php esc_html_e( 'نام نمایشی', 'revayatiran' ); ?><input required minlength="3" name="display_name" value="<?php echo esc_attr( $user->display_name ); ?>"></label><label><?php esc_html_e( 'عنوان حرفه‌ای', 'revayatiran' ); ?><input name="role_title" value="<?php echo esc_attr( $profile['role_title'] ?? '' ); ?>" placeholder="پژوهشگر ارشد"></label><label><?php esc_html_e( 'سازمان یا اندیشکده', 'revayatiran' ); ?><input name="organization" value="<?php echo esc_attr( $profile['organization'] ?? '' ); ?>"></label><label><?php esc_html_e( 'حوزه اصلی', 'revayatiran' ); ?><select name="analyst_field"><option value="0"><?php esc_html_e( 'انتخاب کنید', 'revayatiran' ); ?></option><?php if ( ! is_wp_error( $profile_fields ) ) : foreach ( $profile_fields as $field ) : ?><option value="<?php echo esc_attr( $field->term_id ); ?>" <?php selected( (int) ( $profile['field_id'] ?? 0 ), (int) $field->term_id ); ?>><?php echo esc_html( $field->name ); ?></option><?php endforeach; endif; ?></select></label><label class="rv-profile-fields__wide"><?php esc_html_e( 'تخصص‌ها', 'revayatiran' ); ?><input name="expertise" value="<?php echo esc_attr( $profile['expertise'] ?? '' ); ?>" placeholder="ژئوپلیتیک، اقتصاد سیاسی، رسانه"></label><label class="rv-profile-fields__wide"><?php esc_html_e( 'زندگی‌نامه حرفه‌ای', 'revayatiran' ); ?><textarea name="bio" rows="7" maxlength="3000"><?php echo esc_textarea( $profile['bio'] ?? '' ); ?></textarea></label></div><button type="submit"><?php esc_html_e( 'ذخیره پروفایل', 'revayatiran' ); ?></button></form></section><?php endif; ?>
  <?php if ( $is_analyst ) : ?><section class="rv-dashboard-card rv-dashboard-card--wide" id="submission-form"><div class="rv-dashboard-card__heading"><h2><i class="ph ph-pen-nib"></i><?php echo $editing_submission ? esc_html__( 'ویرایش یادداشت', 'revayatiran' ) : esc_html__( 'یادداشت تازه', 'revayatiran' ); ?></h2><?php if ( $editing_submission ) : ?><a href="<?php echo esc_url( remove_query_arg( 'edit_submission' ) ); ?>"><?php esc_html_e( 'انصراف از ویرایش', 'revayatiran' ); ?></a><?php endif; ?></div><form class="rv-portal-form" method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="revayat_submit_analyst_post"><input type="hidden" name="post_id" value="<?php echo esc_attr( $editing_submission ? $editing_submission->ID : 0 ); ?>"><?php wp_nonce_field( 'revayat_submit_analyst_post', 'revayat_submit_nonce' ); ?><label><?php esc_html_e( 'عنوان یادداشت', 'revayatiran' ); ?><input required minlength="5" name="post_title" value="<?php echo esc_attr( $editing_submission ? $editing_submission->post_title : '' ); ?>"></label><label><?php esc_html_e( 'خلاصه', 'revayatiran' ); ?><textarea name="post_excerpt" rows="3"><?php echo esc_textarea( $editing_submission ? $editing_submission->post_excerpt : '' ); ?></textarea></label><label><?php esc_html_e( 'متن یادداشت', 'revayatiran' ); ?><textarea required name="post_content" rows="12"><?php echo esc_textarea( $editing_submission ? $editing_submission->post_content : '' ); ?></textarea></label><div class="rv-submission-actions"><button type="submit" name="submission_mode" value="submit"><?php esc_html_e( 'ارسال برای بررسی', 'revayatiran' ); ?></button><button type="submit" name="submission_mode" value="draft" class="rv-button-secondary"><?php esc_html_e( 'ذخیره پیش‌نویس', 'revayatiran' ); ?></button></div></form></section><?php endif; ?>
  <section class="rv-dashboard-card rv-dashboard-card--wide"><h2><i class="ph ph-files"></i><?php esc_html_e( 'یادداشت‌های من', 'revayatiran' ); ?></h2><?php if ( $posts ) : ?><div class="rv-submission-list"><?php foreach ( $posts as $submission ) : $editorial_note = class_exists( 'Revayat_Companion_User_Portal' ) ? Revayat_Companion_User_Portal::get_submission_editorial_note( $submission->ID, $user->ID ) : ''; $submission_state = class_exists( 'Revayat_Companion_User_Portal' ) ? Revayat_Companion_User_Portal::get_submission_state( $submission->ID, $user->ID ) : array( 'slug' => $submission->post_status, 'label' => $submission->post_status, 'editable' => false ); ?><article class="rv-submission-item"><div class="rv-submission-item__main"><strong><?php echo wp_kses_post( get_the_title( $submission ) ); ?></strong><time><?php echo esc_html( revayat_en2fa( get_the_date( '', $submission ) ) ); ?></time><?php if ( $editorial_note ) : ?><p class="rv-editorial-note"><i class="ph ph-chat-circle-text"></i><span><b><?php esc_html_e( 'بازخورد تحریریه:', 'revayatiran' ); ?></b> <?php echo esc_html( $editorial_note ); ?></span></p><?php endif; ?></div><div class="rv-submission-item__actions"><span class="rv-status rv-status--<?php echo esc_attr( $submission_state['slug'] ); ?>"><?php echo esc_html( $submission_state['label'] ); ?></span><?php if ( $submission_state['editable'] ) : ?><a href="<?php echo esc_url( add_query_arg( 'edit_submission', $submission->ID, get_permalink() ) . '#submission-form' ); ?>"><i class="ph ph-pencil-simple"></i><?php esc_html_e( 'ویرایش', 'revayatiran' ); ?></a><?php endif; ?></div></article><?php endforeach; ?></div><?php else : ?><p class="rv-form-help"><?php esc_html_e( 'هنوز یادداشتی ارسال نکرده‌اید.', 'revayatiran' ); ?></p><?php endif; ?></section>
 </div>
</div></div>
